#include <atcoder/all>
using mint = atcoder::modint998244353;
using atcoder::segtree;

typedef long long int ll;

ll n;
vector<ll> x, y;

ll mygcd (ll a, ll b) {
	if (b == 0) return a;
	return mygcd(b, a % b);
}
ll myabs (ll x) {
	return (x >= 0) ? x : (-x);
}

vector<pair<ll, ll> > slopes;
vector<pair<ll, ll> > centers;
ll countsamepair (const vector<pair<ll, ll> > &vec) {
	ll sum = 0;
	ll idx = 0;
	while (idx < vec.size()) {
		ll j = idx;
		while (j < vec.size() && vec[j] == vec[idx]) j++;

		ll len = j - idx;
		sum += len * (len-1) / 2;

		idx = j;
	}
	return sum;
}
void solve () {
	for (ll i = 0; i < n; i++) {
		for (ll j = i+1; j < n; j++) {
			// slope
			ll px = x[j] - x[i];
			ll py = y[j] - y[i];

			if (px == 0) {
				px = 0;
				py = 1;
			} else if (py == 0) {
				px = 1;
				py = 0;
			} else {
				if (px < 0) {
					px *= -1;
					py *= -1;
				}
				ll g = mygcd(myabs(px), myabs(py));
				px /= g;
				py /= g;
			}

			slopes.push_back({px, py});

			// center
			centers.push_back({x[i]+x[j], y[i]+y[j]});
		}
	}

	ll ans = 0;
	sort(slopes.begin(), slopes.end());
	ans += countsamepair(slopes);
	sort(centers.begin(), centers.end());
	ans -= countsamepair(centers);

	cout << ans << "\n";


	return;
}

int main (void) {
	std::ios_base::sync_with_stdio(false);
	cin.tie(nullptr);

	cin >> n;
	x.resize(n);
	y.resize(n);
	for (ll i = 0; i < n; i++) {
		cin >> x[i] >> y[i];
	}

	solve();

	return 0;
}
